+					"state": {"status": "completed", "input": {"file_path": "main.go"}, "output": "Applied edit"}}
+			]
+		},
+		{
+			"id": "msg-3",
+			"role": "user",
+			"content": "Also fix util.go",
+			"time": {"created": 1708300010}
