+	if usage.CacheReadTokens != 15 {
+		t.Errorf("expected 15 cache read tokens, got %d", usage.CacheReadTokens)
+	}
+	if usage.CacheCreationTokens != 35 {
+		t.Errorf("expected 35 cache creation tokens, got %d", usage.CacheCreationTokens)
+	}
