+					Type:    EntryTypeUser,
+					Content: msg.Content,
+				})
+			}
+		case "assistant":
+			if msg.Content != "" {
+				entries = append(entries, Entry{
+					Type:    EntryTypeAssistant,
+					Content: msg.Content,
